const text = String($json.query?.text || '').trim();
const safe = text.replace(/"/g, '\"');

const searchFormula = text
  ? `OR(FIND(LOWER("${safe}"), LOWER({Name} & "")) > 0, FIND(LOWER("${safe}"), LOWER({Codigo de Barras} & "")) > 0)`
  : 'TRUE()';

const formula = `AND(({Stock Actual} & "") != "", VALUE({Stock Actual} & "") > 0, ${searchFormula})`;

return [
  {
    json: {
      ok: true,
      text,
      formula
    }
  }
];

try {
  const airtableItems = $items('Airtable');
  const airtableError = airtableItems.find(item => item.json && (item.json.error || item.json.message) && !item.json.id);

  if (airtableError) {
    return [
      {
        json: {
          ok: false,
          error: 'PRODUCT_SEARCH_ERROR',
          message: 'No se pudo consultar el catalogo'
        }
      }
    ];
  }

  const productos = airtableItems
    .filter(item => item.json && item.json.id)
    .map(item => {
      const record = item.json.fields || item.json;
      const barcode = record['Codigo de Barras'];

      return {
        id: item.json.id,
        name: record.Name || '',
        barcode: barcode?.text || barcode || '',
        price: Number(record.Importe || record['Precio x Kg'] || 0),
        weight: Number(record.Peso || 0),
        stock: Number(record['Stock Actual'] || 0)
      };
    });

  return [
    {
      json: {
        ok: true,
        productos
      }
    }
  ];
} catch (error) {
  return [
    {
      json: {
        ok: false,
        error: 'PRODUCT_SEARCH_ERROR',
        message: 'No se pudo consultar el catalogo'
      }
    }
  ];
}
